[{"location":"api/#API-Reference","page":"API Reference","title":"API Reference","text":"","category":"section"},{"location":"api/#Main-Functions","page":"API Reference","title":"Main Functions","text":"","category":"section"},{"location":"api/#download_gtfs_realtime","page":"API Reference","title":"download_gtfs_realtime","text":"","category":"section"},{"location":"api/","page":"API Reference","title":"API Reference","text":"download_gtfs_realtime(url::String, file::String)","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"Download a GTFS Realtime feed from a URL and save it to a file.","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"Arguments:","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"url::String: URL of the GTFS Realtime feed\nfile::String: Local file path to save the feed","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"Examples:","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"download_gtfs_realtime(\"https://api.example.com/gtfs-realtime/trip-updates\", \"trip_updates.pb\")","category":"page"},{"location":"api/#read_gtfs_realtime","page":"API Reference","title":"read_gtfs_realtime","text":"","category":"section"},{"location":"api/","page":"API Reference","title":"API Reference","text":"read_gtfs_realtime(file::String) -> GTFSRealtime","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"Read a GTFS Realtime feed from a protobuf file.","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"Arguments:","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"file::String: Path to the GTFS Realtime protobuf file","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"Returns:","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"GTFSRealtime: Parsed feed data with header and entities","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"Examples:","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"feed = read_gtfs_realtime(\"trip_updates.pb\")","category":"page"},{"location":"api/#Data-Types","page":"API Reference","title":"Data Types","text":"","category":"section"},{"location":"api/#GTFSRealtime","page":"API Reference","title":"GTFSRealtime","text":"","category":"section"},{"location":"api/","page":"API Reference","title":"API Reference","text":"struct GTFSRealtime\n    header::Union{FeedHeader, Nothing}\n    entities::Vector{FeedEntity}\nend","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"Container for GTFS Realtime feed data with convenient access to header and entities.","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"Fields:","category":"page"},{"location":"api/","page":"API Reference","title":"API Reference","text":"header: Feed header containing metadata (or nothing if not present)\nentities: Vector of feed entities (trip updates, vehicle positions, alerts)","category":"page"},{"location":"api/#Helper-Functions","page":"API Reference","title":"Helper Functions","text":"","category":"section"},{"location":"api/#Entity-Type-Checks","page":"API Reference","title":"Entity Type Checks","text":"","category":"section"},{"location":"api/","page":"API Reference","title":"API Reference","text":"has_trip_updates(feed::GTFSRealtime) -> Bool: Check if the feed contains trip update entities\nhas_vehicle_positions(feed::GTFSRealtime) -> Bool: Check if the feed contains vehicle position entities\nhas_alerts(feed::GTFSRealtime) -> Bool: Check if the feed contains alert entities","category":"page"},{"location":"api/#Entity-Extraction","page":"API Reference","title":"Entity Extraction","text":"","category":"section"},{"location":"api/","page":"API Reference","title":"API Reference","text":"get_trip_updates(feed::GTFSRealtime) -> Vector: Get all trip update entities from the feed\nget_vehicle_positions(feed::GTFSRealtime) -> Vector: Get all vehicle position entities from the feed\nget_alerts(feed::GTFSRealtime) -> Vector: Get all alert entities from the feed","category":"page"},{"location":"examples/#Examples","page":"Examples","title":"Examples","text":"","category":"section"},{"location":"examples/#Basic-Usage","page":"Examples","title":"Basic Usage","text":"","category":"section"},{"location":"examples/#Downloading-and-Reading-a-Feed","page":"Examples","title":"Downloading and Reading a Feed","text":"","category":"section"},{"location":"examples/","page":"Examples","title":"Examples","text":"using GTFSRealtimes\n\n# Download a GTFS Realtime feed\ndownload_gtfs_realtime(\"https://api.example.com/gtfs-realtime/trip-updates\", \"trip_updates.pb\")\n\n# Read the downloaded feed\nfeed = read_gtfs_realtime(\"trip_updates.pb\")\n\n# Access feed metadata\nprintln(\"Feed version: \", feed.header.gtfs_realtime_version)\nprintln(\"Feed timestamp: \", feed.header.timestamp)\nprintln(\"Number of entities: \", length(feed.entities))","category":"page"},{"location":"examples/#Working-with-Different-Entity-Types","page":"Examples","title":"Working with Different Entity Types","text":"","category":"section"},{"location":"examples/","page":"Examples","title":"Examples","text":"using GTFSRealtimes\n\nfeed = read_gtfs_realtime(\"feed.pb\")\n\n# Check what types of entities are in the feed\nif has_trip_updates(feed)\n    println(\"Feed contains trip updates\")\n    trip_updates = get_trip_updates(feed)\n    println(\"Number of trip updates: \", length(trip_updates))\nend\n\nif has_vehicle_positions(feed)\n    println(\"Feed contains vehicle positions\")\n    vehicle_positions = get_vehicle_positions(feed)\n    println(\"Number of vehicle positions: \", length(vehicle_positions))\nend\n\nif has_alerts(feed)\n    println(\"Feed contains alerts\")\n    alerts = get_alerts(feed)\n    println(\"Number of alerts: \", length(alerts))\nend","category":"page"},{"location":"examples/#Processing-Trip-Updates","page":"Examples","title":"Processing Trip Updates","text":"","category":"section"},{"location":"examples/","page":"Examples","title":"Examples","text":"using GTFSRealtimes\n\nfeed = read_gtfs_realtime(\"trip_updates.pb\")\n\nif has_trip_updates(feed)\n    for entity in get_trip_updates(feed)\n        trip_update = entity.trip_update\n\n        # Access trip information\n        trip = trip_update.trip\n        println(\"Trip ID: \", trip.trip_id)\n        println(\"Route ID: \", trip.route_id)\n\n        # Process stop time updates\n        for stop_time_update in trip_update.stop_time_update\n            println(\"Stop ID: \", stop_time_update.stop_id)\n\n            if stop_time_update.arrival !== nothing\n                println(\"Arrival delay: \", stop_time_update.arrival.delay)\n            end\n\n            if stop_time_update.departure !== nothing\n                println(\"Departure delay: \", stop_time_update.departure.delay)\n            end\n        end\n    end\nend","category":"page"},{"location":"examples/#Processing-Vehicle-Positions","page":"Examples","title":"Processing Vehicle Positions","text":"","category":"section"},{"location":"examples/","page":"Examples","title":"Examples","text":"using GTFSRealtimes\n\nfeed = read_gtfs_realtime(\"vehicle_positions.pb\")\n\nif has_vehicle_positions(feed)\n    for entity in get_vehicle_positions(feed)\n        vehicle = entity.vehicle\n\n        # Access vehicle information\n        if vehicle.vehicle !== nothing\n            println(\"Vehicle ID: \", vehicle.vehicle.id)\n            println(\"Label: \", vehicle.vehicle.label)\n        end\n\n        # Access position information\n        if vehicle.position !== nothing\n            pos = vehicle.position\n            println(\"Latitude: \", pos.latitude)\n            println(\"Longitude: \", pos.longitude)\n            println(\"Bearing: \", pos.bearing)\n            println(\"Speed: \", pos.speed)\n        end\n\n        # Access trip information\n        if vehicle.trip !== nothing\n            trip = vehicle.trip\n            println(\"Trip ID: \", trip.trip_id)\n            println(\"Route ID: \", trip.route_id)\n        end\n    end\nend","category":"page"},{"location":"examples/#Processing-Alerts","page":"Examples","title":"Processing Alerts","text":"","category":"section"},{"location":"examples/","page":"Examples","title":"Examples","text":"using GTFSRealtimes\n\nfeed = read_gtfs_realtime(\"alerts.pb\")\n\nif has_alerts(feed)\n    for entity in get_alerts(feed)\n        alert = entity.alert\n\n        # Access alert information\n        for informed_entity in alert.informed_entity\n            if informed_entity.route_id !== nothing\n                println(\"Affected route: \", informed_entity.route_id)\n            end\n\n            if informed_entity.stop_id !== nothing\n                println(\"Affected stop: \", informed_entity.stop_id)\n            end\n        end\n\n        # Access alert text\n        for text in alert.header_text.translation\n            println(\"Alert header: \", text.text)\n        end\n\n        for text in alert.description_text.translation\n            println(\"Alert description: \", text.text)\n        end\n    end\nend","category":"page"},{"location":"examples/#Error-Handling","page":"Examples","title":"Error Handling","text":"","category":"section"},{"location":"examples/","page":"Examples","title":"Examples","text":"using GTFSRealtimes\n\n# Handle download errors\ntry\n    download_gtfs_realtime(\"https://invalid-url.com/feed\", \"feed.pb\")\ncatch e\n    if isa(e, ArgumentError)\n        println(\"Download failed: \", e.msg)\n    else\n        println(\"Unexpected error: \", e)\n    end\nend\n\n# Handle read errors\ntry\n    feed = read_gtfs_realtime(\"nonexistent.pb\")\ncatch e\n    if isa(e, ArgumentError)\n        println(\"Read failed: \", e.msg)\n    else\n        println(\"Unexpected error: \", e)\n    end\nend","category":"page"},{"location":"#GTFSRealtimes.jl","page":"Home","title":"GTFSRealtimes.jl","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"A Julia package for downloading and reading GTFS Realtime feeds using Protocol Buffers.","category":"page"},{"location":"#Overview","page":"Home","title":"Overview","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"GTFSRealtimes.jl provides a comprehensive solution for working with GTFS Realtime feeds in Julia. It supports downloading feeds from transit agencies and parsing them using the official GTFS Realtime protobuf specification.","category":"page"},{"location":"#Key-Features","page":"Home","title":"Key Features","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"GTFS Realtime Support: Download and read GTFS Realtime feeds from transit agencies\nProtocol Buffer Integration: Native support for GTFS Realtime protobuf format\nAutomatic Updates: Protobuf definitions are automatically generated from the official GTFS Realtime specification\nCompression Support: Handles gzip-compressed feeds commonly used in production","category":"page"},{"location":"#Quick-Start","page":"Home","title":"Quick Start","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"using GTFSRealtimes\n\n# Download a GTFS Realtime feed\ndownload_gtfs_realtime(\"https://api.example.com/gtfs-realtime/trip-updates\", \"trip_updates.pb\")\n\n# Read the downloaded feed\nfeed = read_gtfs_realtime(\"trip_updates.pb\")\n\n# Access feed data\nprintln(\"Feed version: \", feed.header.gtfs_realtime_version)\nprintln(\"Number of entities: \", length(feed.entities))","category":"page"},{"location":"#Installation","page":"Home","title":"Installation","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"using Pkg\nPkg.add(url=\"https://github.com/moviro-hub/GTFSRealtimes.jl\")","category":"page"},{"location":"#GTFS-Realtime-Specification","page":"Home","title":"GTFS Realtime Specification","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"This package implements the official GTFS Realtime specification: https://gtfs.org/documentation/realtime/reference/","category":"page"},{"location":"","page":"Home","title":"Home","text":"The protobuf definitions are automatically generated from the official specification at: https://gtfs.org/documentation/realtime/gtfs-realtime.proto","category":"page"},{"location":"#License","page":"Home","title":"License","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"This package is licensed under the MIT License.","category":"page"}]
